    public static Quaternion Turn(HandPose pose, int bone, bool right, float amount)
    {
        var t = pose.Turns;
        var q = new Quaternion(t[bone * 4], t[bone * 4 + 1], t[bone * 4 + 2], t[bone * 4 + 3]);
        if(right)
            q = new Quaternion(-q.X, -q.Y, q.Z, q.W);
        amount = Math.Clamp(amount, 0f, 1f);
        return amount >= 0.999f ? Quaternion.Normalize(q) : Quaternion.Normalize(Quaternion.Slerp(Quaternion.Identity, q, amount));
    }

    private static string Side(bool right) => right ? "_r" : "_l";

    /// <summary>Turns the fingers of one hand into the pose. Bones the character doesn't have are skipped.</summary>
    public static void Apply(ActorRig rig, HandPose pose, bool right, float amount, Func<string, bool>? has)
    {
        for(int i = 0; i < Bones.Length; i++)
        {
            string name = Bones[i] + Side(right);
            if(has != null && !has(name))
                continue;
            var goal = rig.GetOrAdd(name);
            goal.Enabled = true;
            goal.Space = GoalSpace.FollowBody;
            goal.HomeSpace = GoalSpace.FollowBody;
            goal.ParentActor = 0;
            goal.ParentBone = null;
            goal.HoldPosition = false;
            goal.Mirror = MirrorMode.Off;
            goal.LockRotation = true;
            goal.PendingWorldPosition = null;
            goal.PendingWorldRotation = null;
            goal.PendingRestTurn = Turn(pose, i, right, amount);
        }
    }

    /// <summary>Lets go of every finger of one hand (back to the animation's fingers).</summary>
    public static int Clear(ActorRig rig, bool right)
    {
        string side = Side(right);
        return rig.Goals.RemoveAll(g => g.Bone.EndsWith(side, StringComparison.Ordinal) && Bones.Any(b => g.Bone == b + side));
    }
}
